items.command:
/bin/zsh -lc "python3 -c 'import zlib,struct; d=open(\"red.png\",\"rb\").read(); p=8; out=[]
while p<len(d):
 n=struct.unpack(\">I\",d[p:p+4])[0]; t=d[p+4:p+8]; x=d[p+8:p+8+n]; p+=12+n
 if t==b\"IDAT\": out.append(x)
print(list(zlib.decompress(b\"\".join(out))))'"

